#include <windows.h>
#include <winternl.h>
#include <stdio.h>

typedef NTSTATUS (NTAPI *LdrLoadDllFn)(PCWSTR, PULONG, PUNICODE_STRING,
    PVOID*);
typedef NTSTATUS (NTAPI *LdrUnloadDllFn)(PVOID);

int main() {
    HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
    auto ldrLoadDll = reinterpret_cast<LdrLoadDllFn>(
        GetProcAddress(ntdll, "LdrLoadDll"));
    auto ldrUnloadDll = reinterpret_cast<LdrUnloadDllFn>(
        GetProcAddress(ntdll, "LdrUnloadDll"));
    if (ldrLoadDll == nullptr || ldrUnloadDll == nullptr) {
        return 1;
    }

    UNICODE_STRING name = {};
    RtlInitUnicodeString(&name, L"kernel32.dll");
    PVOID module = nullptr;
    NTSTATUS status = ldrLoadDll(nullptr, nullptr, &name, &module);
    if (status >= 0 && module != nullptr) {
        ldrUnloadDll(module);
    }
    return 0;
}

#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtAdjustPrivilegesToken(HANDLE, BOOLEAN,
    PTOKEN_PRIVILEGES, ULONG, PTOKEN_PRIVILEGES, PULONG);

int main() {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token)) {
        return 1;
    }

    LUID luid = {};
    LookupPrivilegeValueA(nullptr, SE_CHANGE_NOTIFY_NAME, &luid);

    TOKEN_PRIVILEGES privileges = {};
    privileges.PrivilegeCount = 1;
    privileges.Privileges[0].Luid = luid;
    privileges.Privileges[0].Attributes = 0;

    TOKEN_PRIVILEGES previous = {};
    ULONG length = sizeof(previous);
    NTSTATUS status = NtAdjustPrivilegesToken(token, FALSE, &privileges,
        sizeof(previous), &previous, &length);
    if (status >= 0) {
        NtAdjustPrivilegesToken(token, FALSE, &previous, 0, nullptr,
            nullptr);
    }

    CloseHandle(token);
    return 0;
}

