extern "C" NTSTATUS NTAPI NtContinue(PCONTEXT, BOOLEAN);
extern "C" VOID NTAPI RtlCaptureContext(PCONTEXT);

int main() {
    CONTEXT context = {};
    RtlCaptureContext(&context);

    static volatile LONG resumed = 0;
    if (InterlockedCompareExchange(&resumed, 1, 0) == 0) {
        printf("Calling NtContinue to restore the captured context.\n");
        NTSTATUS status = NtContinue(&context, FALSE);
        printf("NtContinue failed: 0x%08lx\n", status);
    } else {
        printf("Execution resumed after NtContinue.\n");
    }
    return 0;
}

