#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtOpenFile(PHANDLE, ACCESS_MASK,
    POBJECT_ATTRIBUTES, PIO_STATUS_BLOCK, ULONG, ULONG);
extern "C" NTSTATUS NTAPI NtCreateSection(PHANDLE, ACCESS_MASK,
    POBJECT_ATTRIBUTES, PLARGE_INTEGER, ULONG, ULONG, HANDLE);
extern "C" NTSTATUS NTAPI NtCreateProcess(PHANDLE, ACCESS_MASK,
    POBJECT_ATTRIBUTES, HANDLE, BOOLEAN, HANDLE, HANDLE, HANDLE);
extern "C" NTSTATUS NTAPI NtTerminateProcess(HANDLE, NTSTATUS);

int main() {
    UNICODE_STRING image = {};
    RtlInitUnicodeString(&image,
        L"\\??\\C:\\Windows\\System32\\notepad.exe");

    OBJECT_ATTRIBUTES attributes = {};
    InitializeObjectAttributes(&attributes, &image, OBJ_CASE_INSENSITIVE,
        nullptr, nullptr);

    HANDLE file = nullptr;
    IO_STATUS_BLOCK iosb = {};
    NTSTATUS status = NtOpenFile(&file, GENERIC_READ | SYNCHRONIZE,
        &attributes, &iosb, FILE_SHARE_READ, FILE_SYNCHRONOUS_IO_NONALERT);
    if (status < 0) {
        return 1;
    }

    HANDLE section = nullptr;
    status = NtCreateSection(&section, SECTION_ALL_ACCESS, nullptr, nullptr,
        PAGE_EXECUTE, SEC_IMAGE, file);
    if (status >= 0) {
        HANDLE process = nullptr;
        status = NtCreateProcess(&process, PROCESS_ALL_ACCESS, nullptr,
            GetCurrentProcess(), FALSE, section, nullptr, nullptr);
        if (status >= 0) {
            printf("Created process object: %p\n", process);
            NtTerminateProcess(process, 0);
            NtClose(process);
        }
        NtClose(section);
    }

    NtClose(file);
    return 0;
}

