#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtCreateThread(PHANDLE, ACCESS_MASK,
    POBJECT_ATTRIBUTES, HANDLE, PCLIENT_ID, PCONTEXT, PVOID, BOOLEAN);
extern "C" NTSTATUS NTAPI NtTerminateThread(HANDLE, NTSTATUS);
extern "C" VOID NTAPI RtlCaptureContext(PCONTEXT);
extern "C" VOID NTAPI RtlExitUserThread(NTSTATUS);

typedef struct _MY_INITIAL_TEB {
    struct {
        PVOID OldStackBase;
        PVOID OldStackLimit;
    } OldInitialTeb;
    PVOID StackBase;
    PVOID StackLimit;
    PVOID StackAllocationBase;
} MY_INITIAL_TEB;

static VOID NTAPI ThreadStart() {
    RtlExitUserThread(0);
}

int main() {
    const SIZE_T stackSize = 1024 * 1024;
    PVOID stack = VirtualAlloc(nullptr, stackSize, MEM_COMMIT | MEM_RESERVE,
        PAGE_READWRITE);
    if (stack == nullptr) {
        return 1;
    }

    CONTEXT context = {};
    RtlCaptureContext(&context);
#ifdef _M_X64
    context.Rip = reinterpret_cast<DWORD64>(ThreadStart);
    context.Rsp = reinterpret_cast<DWORD64>(stack) + stackSize - 8;
    context.Rcx = 0;
#else
    context.Eip = reinterpret_cast<DWORD>(ThreadStart);
    context.Esp = reinterpret_cast<DWORD>(stack) + static_cast<DWORD>(stackSize) - 4;
    context.Ecx = 0;
#endif

    MY_INITIAL_TEB initialTeb = {};
    initialTeb.StackAllocationBase = stack;
    initialTeb.StackLimit = stack;
    initialTeb.StackBase = static_cast<BYTE*>(stack) + stackSize;

    HANDLE thread = nullptr;
    CLIENT_ID clientId = {};
    NTSTATUS status = NtCreateThread(&thread, THREAD_ALL_ACCESS, nullptr,
        GetCurrentProcess(), &clientId, &context, &initialTeb, TRUE);
    if (status >= 0) {
        printf("Created suspended thread: %p\n", thread);
        NtTerminateThread(thread, 0);
        NtClose(thread);
    } else {
        printf("NtCreateThread failed: 0x%08lx\n", status);
    }

    VirtualFree(stack, 0, MEM_RELEASE);
    return 0;
}

