#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtCreateUserProcess(PHANDLE, PHANDLE, ACCESS_MASK,
    ACCESS_MASK, POBJECT_ATTRIBUTES, POBJECT_ATTRIBUTES, ULONG, ULONG,
    PRTL_USER_PROCESS_PARAMETERS, PVOID, PVOID);
extern "C" NTSTATUS NTAPI NtTerminateProcess(HANDLE, NTSTATUS);
extern "C" NTSTATUS NTAPI RtlCreateProcessParametersEx(
    PRTL_USER_PROCESS_PARAMETERS*, PCUNICODE_STRING, PCUNICODE_STRING,
    PCUNICODE_STRING, PCUNICODE_STRING, PVOID, PCUNICODE_STRING,
    PCUNICODE_STRING, PCUNICODE_STRING, PCUNICODE_STRING, ULONG);
extern "C" NTSTATUS NTAPI RtlDestroyProcessParameters(
    PRTL_USER_PROCESS_PARAMETERS);

typedef enum _MY_PS_CREATE_STATE {
    MyPsCreateInitialState = 0,
    MyPsCreateSuccess = 6
} MY_PS_CREATE_STATE;

typedef struct _MY_PS_CREATE_INFO {
    SIZE_T Size;
    MY_PS_CREATE_STATE State;
    union {
        struct {
            ULONG InitFlags;
            ACCESS_MASK AdditionalFileAccess;
        } InitState;
        struct { HANDLE FileHandle; } FailSection;
        struct { USHORT DllCharacteristics; } ExeFormat;
        struct { HANDLE IFEOKey; } ExeName;
        struct {
            ULONG OutputFlags;
            HANDLE FileHandle;
            HANDLE SectionHandle;
            ULONGLONG UserProcessParametersNative;
            ULONG UserProcessParametersWow64;
            ULONG CurrentParameterFlags;
            ULONGLONG PebAddressNative;
            ULONG PebAddressWow64;
            ULONGLONG ManifestAddress;
            ULONG ManifestSize;
        } SuccessState;
    };
} MY_PS_CREATE_INFO;

typedef struct _MY_PS_ATTRIBUTE {
    ULONG_PTR Attribute;
    SIZE_T Size;
    union {
        ULONG_PTR Value;
        PVOID ValuePtr;
    };
    PSIZE_T ReturnLength;
} MY_PS_ATTRIBUTE;

typedef struct _MY_PS_ATTRIBUTE_LIST {
    SIZE_T TotalLength;
    MY_PS_ATTRIBUTE Attributes[1];
} MY_PS_ATTRIBUTE_LIST;

int main() {
    UNICODE_STRING image = {};
    RtlInitUnicodeString(&image,
        L"\\??\\C:\\Windows\\System32\\notepad.exe");

    PRTL_USER_PROCESS_PARAMETERS parameters = nullptr;
    NTSTATUS status = RtlCreateProcessParametersEx(&parameters, &image,
        nullptr, nullptr, &image, nullptr, nullptr, nullptr, nullptr, nullptr,
        1 /* RTL_USER_PROC_PARAMS_NORMALIZED */);
    if (status < 0) {
        return 1;
    }

    MY_PS_ATTRIBUTE_LIST attributes = {};
    attributes.TotalLength = sizeof(attributes);
    attributes.Attributes[0].Attribute = 0x00020005; // PsAttributeImageName
    attributes.Attributes[0].Size = image.Length + sizeof(wchar_t);
    attributes.Attributes[0].ValuePtr = image.Buffer;

    MY_PS_CREATE_INFO createInfo = {};
    createInfo.Size = sizeof(createInfo);
    createInfo.State = MyPsCreateInitialState;

    HANDLE process = nullptr;
    HANDLE thread = nullptr;
    status = NtCreateUserProcess(&process, &thread, PROCESS_ALL_ACCESS,
        THREAD_ALL_ACCESS, nullptr, nullptr, 0,
        1 /* THREAD_CREATE_FLAGS_CREATE_SUSPENDED */, parameters, &createInfo,
        &attributes);
    if (status >= 0) {
        printf("Created suspended process %p with thread %p\n", process,
            thread);
        NtTerminateProcess(process, 0);
        NtClose(thread);
        NtClose(process);
    } else {
        printf("NtCreateUserProcess failed: 0x%08lx\n", status);
    }

    RtlDestroyProcessParameters(parameters);
    return 0;
}

