#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtAllocateVirtualMemory(HANDLE, PVOID*, ULONG_PTR,
    PSIZE_T, ULONG, ULONG);
extern "C" NTSTATUS NTAPI NtProtectVirtualMemory(HANDLE, PVOID*, PSIZE_T,
    ULONG, PULONG);
extern "C" NTSTATUS NTAPI NtFreeVirtualMemory(HANDLE, PVOID*, PSIZE_T,
    ULONG);

int main() {
    PVOID base = nullptr;
    SIZE_T size = 4096;
    NtAllocateVirtualMemory(GetCurrentProcess(), &base, 0, &size,
        MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);

    ULONG old_protection = 0;
    if (base != nullptr &&
        NtProtectVirtualMemory(GetCurrentProcess(), &base, &size,
            PAGE_READONLY, &old_protection) >= 0) {
        NtProtectVirtualMemory(GetCurrentProcess(), &base, &size,
            old_protection, &old_protection);
    }

    NtFreeVirtualMemory(GetCurrentProcess(), &base, &size, MEM_RELEASE);
    return 0;
}

