    HANDLE directory = nullptr;
    NTSTATUS status = NtCreateFile(&directory,
        FILE_LIST_DIRECTORY | SYNCHRONIZE, &attributes, &status_block,
        nullptr, FILE_ATTRIBUTE_NORMAL,
