#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

typedef VOID (NTAPI *MY_APC_ROUTINE)(PVOID, PVOID, PVOID);

static HANDLE g_event = nullptr;

static VOID NTAPI ApcRoutine(PVOID, PVOID, PVOID) {
    SetEvent(g_event);
}

int main() {
    g_event = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    HANDLE thread = OpenThread(THREAD_SET_CONTEXT, FALSE, GetCurrentThreadId());
    if (g_event == nullptr || thread == nullptr) {
        return 1;
    }

    NTSTATUS status = NtQueueApcThread(thread, ApcRoutine, nullptr, nullptr, nullptr);
    if (status >= 0) {
        SleepEx(0, TRUE); // Deliver the queued user APC.
        WaitForSingleObject(g_event, 1000);
        printf("APC executed: %s\n",
            WaitForSingleObject(g_event, 0) == WAIT_OBJECT_0 ? "yes" : "no");
    } else {
        printf("APC queue failed: 0x%08lx\n", status);
    }

    CloseHandle(thread);
    CloseHandle(g_event);
    return 0;
}

