#include <windows.h>
#include <winternl.h>
#include <stdio.h>
#include <string.h>

extern "C" NTSTATUS NTAPI NtShutdownSystem(ULONG Action);

typedef enum _MY_SHUTDOWN_ACTION {
    MyShutdownNoReboot = 0,
    MyShutdownReboot = 1,
    MyShutdownPowerOff = 2
} MY_SHUTDOWN_ACTION;

static BOOL EnableShutdownPrivilege() {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token)) {
        return FALSE;
    }

    LUID luid = {};
    BOOL enabled = LookupPrivilegeValueW(nullptr, SE_SHUTDOWN_NAME, &luid);
    if (enabled) {
        TOKEN_PRIVILEGES privileges = {};
        privileges.PrivilegeCount = 1;
        privileges.Privileges[0].Luid = luid;
        privileges.Privileges[0].Attributes = SE_PRIVILEGE_ENABLED;
        enabled = AdjustTokenPrivileges(token, FALSE, &privileges, 0,
            nullptr, nullptr);
        if (enabled && GetLastError() == ERROR_NOT_ALL_ASSIGNED) {
            enabled = FALSE;
        }
    }

    CloseHandle(token);
    return enabled;
}

int main(int argc, char** argv) {
    if (argc < 2 || strcmp(argv[1], "--apply") != 0) {
        printf("Dry run. Pass --apply to power off the machine.\n");
        return 0;
    }

    if (!EnableShutdownPrivilege()) {
        printf("Could not enable SeShutdownPrivilege.\n");
        return 1;
    }

    NTSTATUS status = NtShutdownSystem(MyShutdownPowerOff);
    printf("NtShutdownSystem status: 0x%08lx\n", status);
    return status >= 0 ? 0 : 1;
}

