    }

    void* base = region;
    SIZE_T size = 4096;
    NTSTATUS status = NtLockVirtualMemory(GetCurrentProcess(), &base, &size, 1);
    printf("Lock status: 0x%08lx\n", status);
    if (status >= 0) {
        NtUnlockVirtualMemory(GetCurrentProcess(), &base, &size, 1);
    }

    VirtualFree(region, 0, MEM_RELEASE);
    return 0;
}

