extern "C" NTSTATUS NTAPI NtCreateEvent(PHANDLE, ACCESS_MASK,
    PCOBJECT_ATTRIBUTES, EVENT_TYPE, BOOLEAN);
extern "C" NTSTATUS NTAPI NtResetEvent(HANDLE, PLONG);

int main() {
    HANDLE event = nullptr;
    NTSTATUS status = NtCreateEvent(&event, EVENT_ALL_ACCESS, nullptr,
        NotificationEvent, TRUE);
    if (status < 0) {
        return 1;
    }

    LONG previous = 0;
    status = NtResetEvent(event, &previous);
    printf("Reset status: 0x%08lx, previous state: %ld\n", status, previous);

    NtClose(event);
    return 0;
}

