#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtQueryObject(HANDLE, OBJECT_INFORMATION_CLASS,
    PVOID, ULONG, PULONG);

int main() {
    OBJECT_BASIC_INFORMATION info = {};
    ULONG returned = 0;
    NTSTATUS status = NtQueryObject(GetCurrentProcess(), ObjectBasicInformation,
        &info, sizeof(info), &returned);
    if (status >= 0) {
        printf("Handles: %lu, pointers: %lu\n", info.HandleCount,
            info.PointerCount);
    }
    return 0;
