#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtQuerySecurityObject(HANDLE,
    SECURITY_INFORMATION, PSECURITY_DESCRIPTOR, ULONG, PULONG);

int main() {
    BYTE buffer[1024] = {};
    ULONG needed = 0;
    SECURITY_INFORMATION requested = OWNER_SECURITY_INFORMATION |
        GROUP_SECURITY_INFORMATION | DACL_SECURITY_INFORMATION;
    NTSTATUS status = NtQuerySecurityObject(GetCurrentProcess(), requested,
        buffer, sizeof(buffer), &needed);
    if (status >= 0) {
        printf("Security descriptor length: %lu bytes\n", needed);
    }
    return 0;
}

#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtQuerySystemInformation(SYSTEM_INFORMATION_CLASS,
    PVOID, ULONG, PULONG);

struct MY_SYSTEM_BASIC_INFORMATION {
    ULONG Reserved;
    ULONG TimerResolution;
    ULONG PageSize;
    ULONG NumberOfPhysicalPages;
    ULONG LowestPhysicalPageNumber;
    ULONG HighestPhysicalPageNumber;
    ULONG AllocationGranularity;
    ULONG_PTR MinimumUserModeAddress;
    ULONG_PTR MaximumUserModeAddress;
    KAFFINITY ActiveProcessorsAffinityMask;
    CCHAR NumberOfProcessors;
};

int main() {
    MY_SYSTEM_BASIC_INFORMATION info = {};
    ULONG returned = 0;
    NTSTATUS status = NtQuerySystemInformation(SystemBasicInformation, &info,
        sizeof(info), &returned);
    if (status >= 0) {
        printf("Processors: %u, page size: %lu\n", info.NumberOfProcessors,
            info.PageSize);
    }
    return 0;
}

#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtQuerySystemTime(PLARGE_INTEGER);

int main() {
    LARGE_INTEGER systemTime = {};
    NTSTATUS status = NtQuerySystemTime(&systemTime);
    if (status < 0) {
        return 1;
    }

    FILETIME fileTime = {};
    fileTime.dwLowDateTime = systemTime.LowPart;
    fileTime.dwHighDateTime = systemTime.HighPart;
    SYSTEMTIME local = {};
    if (FileTimeToSystemTime(&fileTime, &local)) {
        printf("%04u-%02u-%02u %02u:%02u:%02u UTC\n", local.wYear,
            local.wMonth, local.wDay, local.wHour, local.wMinute,
            local.wSecond);
    }
    return 0;
}

