extern "C" PVOID NTAPI RtlAllocateHeap(PVOID, ULONG, SIZE_T);
extern "C" BOOLEAN NTAPI RtlFreeHeap(PVOID, ULONG, PVOID);

int main() {
    PVOID block = RtlAllocateHeap(GetProcessHeap(), HEAP_ZERO_MEMORY, 64);
    if (block == nullptr) {
        return 1;
    }

    memcpy(block, "example", 8);
    printf("Allocated block: %p\n", block);
    RtlFreeHeap(GetProcessHeap(), 0, block);
    return 0;
}

