#pragma comment(lib, "ntdll.lib")

extern "C" PVOID NTAPI RtlAllocateHeap(PVOID, ULONG, SIZE_T);
extern "C" BOOLEAN NTAPI RtlFreeHeap(PVOID, ULONG, PVOID);

int main() {
    PVOID block = RtlAllocateHeap(GetProcessHeap(), 0, 64);
    if (block == nullptr) {
        return 1;
    }

    BOOLEAN freed = RtlFreeHeap(GetProcessHeap(), 0, block);
    printf("Freed: %s\n", freed ? "yes" : "no");
    return freed ? 0 : 1;
}

#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" USHORT NTAPI RtlCaptureStackBackTrace(ULONG, ULONG, PVOID*,
    PULONG);

int main() {
    PVOID frames[8] = {};
    ULONG hash = 0;
    USHORT captured = RtlCaptureStackBackTrace(0,
        static_cast<ULONG>(sizeof(frames) / sizeof(frames[0])), frames, &hash);
    printf("Captured %u frames, hash 0x%08lx\n", captured, hash);
    for (USHORT i = 0; i < captured; ++i) {
        printf("  frame %u: %p\n", i, frames[i]);
    }
    return 0;
}

