#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI LdrFindEntryForAddress(PVOID, PVOID*);

struct MY_LDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
    LIST_ENTRY InMemoryOrderLinks;
    LIST_ENTRY InInitializationOrderLinks;
    PVOID DllBase;
    PVOID EntryPoint;
    ULONG SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
};

int main() {
    PVOID entry = nullptr;
    NTSTATUS status = LdrFindEntryForAddress(GetModuleHandleW(nullptr), &entry);
    if (status >= 0) {
        auto data = reinterpret_cast<MY_LDR_DATA_TABLE_ENTRY*>(entry);
        printf("Module base: %p, size: %lu bytes\n", data->DllBase,
            data->SizeOfImage);
    }
    return 0;
}
